question.answer:
package main

import (
	"errors"
	"fmt"
)

var ErrOutOfStock = errors.New("out of stock")

// pick is fixed. It returns ErrOutOfStock when the warehouse has none of item.
func pick(item string, stock map[string]int) error {
	if stock[item] == 0 {
		return ErrOutOfStock
	}
	return nil
}

func pack(item string, stock map[string]int) error {
	if err := pick(item, stock); err != nil {
		return fmt.Errorf("pack %s: %w", item, err)
	}
	return nil
}

func outOfStock(err error) bool {
	return errors.Is(err, ErrOutOfStock)
}

