question.answer:
package main

import (
	"errors"
	"fmt"
)

var ErrClosed = errors.New("wire closed")

// QuotaError reports a message longer than the wire allows.
type QuotaError struct {
	Limit int
	Size  int
}

// send is fixed. It returns ErrClosed when limit is 0 and a *QuotaError
// when size exceeds limit.
func send(size, limit int) error {
	if limit < 1 {
		return ErrClosed
	}
	if size > limit {
		return &QuotaError{Limit: limit, Size: size}
	}
	return nil
}

func (e *QuotaError) Error() string {
	return fmt.Sprintf("size %d exceeds limit %d", e.Size, e.Limit)
}

func relay(stations []string, size, limit int) error {
	err := send(size, limit)
	if err != nil {
		for _, station := range stations {
			err = fmt.Errorf("%s: %w", station, err)
		}
	}
	return err
}

func overBy(err error) int {
	var q *QuotaError
	if errors.As(err, &q) {
		return q.Size - q.Limit
	}
	return 0
}

func closed(err error) bool {
	return errors.Is(err, ErrClosed)
}

