question.answer:
package main

import "fmt"

// Finding is one inspector's objection to a form.
type Finding struct {
	Line int
	Text string
}

// inspect is fixed. It returns the first fault on the form, or nil.
func inspect(form []string) *Finding {
	for i, line := range form {
		if line == "" {
			return &Finding{Line: i + 1, Text: "blank"}
		}
		if len(line) > 12 {
			return &Finding{Line: i + 1, Text: "too long"}
		}
	}
	return nil
}

func (f *Finding) Error() string {
	return fmt.Sprintf("line %d: %s", f.Line, f.Text)
}

func review(form []string) error {
	if f := inspect(form); f != nil {
		return f
	}
	return nil
}

func verdict(err error) string {
	if err == nil {
		return "clean"
	}
	return err.Error()
}

