question.answer:
package main

import (
	"fmt"
	"strconv"
	"strings"
)

// parseAge converts an age field to a number. Ages are never negative.
func parseAge(field string) (int, error) {
	n, err := strconv.Atoi(field)
	if err != nil {
		return 0, fmt.Errorf("parse age %q: %w", field, err)
	}
	if n < 0 {
		return 0, fmt.Errorf("negative age %d", n)
	}
	return n, nil
}

// ageOf finds name in roster lines of the form "name,age".
func ageOf(roster []string, name string) (int, error) {
	for _, line := range roster {
		fields := strings.Split(line, ",")
		if len(fields) != 2 {
			return 0, fmt.Errorf("malformed line %q", line)
		}
		if fields[0] != name {
			continue
		}
		age, err := parseAge(fields[1])
		if err != nil {
			return 0, fmt.Errorf("%s: %w", name, err)
		}
		return age, nil
	}
	return 0, fmt.Errorf("no entry for %s", name)
}

testcode.text:
roster := []string{"Ada,36", "Bob,7"}
age, err := ageOf(roster, "Bob")
fmt.Println(age, err == nil)
